import pandas as pd
import re

def parse_date(s):
    if pd.isna(s):
        return pd.NaT
    s = str(s).strip()
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
        return pd.to_datetime(s, format='%Y-%m-%d', errors='coerce')
    # also handle D Mon YYYY
    return pd.to_datetime(s, dayfirst=True, errors='coerce')

tests = ['2025-06-04','2025-04-03','03/04/2025','3 Apr 2025','25/04/2025','2025-08-01','18 Jul 2025']
for t in tests:
    print(t, parse_date(t))
